const item = $input.first().json;
return [{
  json: {
    url: item.url || '',
    status: item.status || 'unknown',
    subStatus: item.subStatus || '',
    pageCount: item.pageCount || 0,
    pagesExtracted: item.pagesExtracted || 0,
    ocrPages: item.ocrPages || 0,
    charCount: item.charCount || 0,
    title: item.title || '',
    text: item.text || '',
    error: item.error || ''
  }
}];
